    return [...RESIDUAL_BEARERS]
      .map((b) => ({
        ...b,
        value:
          ladderMetric === "sharePct"
            ? b.sharePct
            : ladderMetric === "cumulativePct"
              ? b.cumulativePct
              : b.sharePct - b.priorSharePct,
      }))
      .sort((a, b) =>
        ladderMetric === "deltaPp" ? a.value - b.value : b.value - a.value,
      );
